sign_ins = [
    {"user": "ada@example.com", "network": "trusted", "device_compliant": True, "mfa_registered": True, "risk": "low"},
    {"user": "grace@example.com", "network": "untrusted", "device_compliant": False, "mfa_registered": True, "risk": "medium"},
    {"user": "alan@example.com", "network": "untrusted", "device_compliant": False, "mfa_registered": False, "risk": "high"},
    {"user": "linus@example.com", "network": "trusted", "device_compliant": False, "mfa_registered": True, "risk": "low"},
]

def evaluate(sign_in):
    if sign_in["risk"] == "high":
        return "bloqueado: riesgo de inicio de sesion alto"
    if sign_in["network"] == "trusted" and sign_in["device_compliant"]:
        return "permitido: dispositivo conforme en red de confianza"
    if not sign_in["mfa_registered"]:
        return "bloqueado: debe registrar autenticacion multifactor"
    if sign_in["risk"] == "medium":
        return "permitido con autenticacion multifactor obligatoria"
    return "permitido con autenticacion multifactor"

for s in sign_ins:
    print(f"{s['user']}: {evaluate(s)}")
